        "637798": {
         "recordId": "637798",
         "athleteName": "Tyrone Tracy Jr.",
         "positionAbbr": "RB",
         "teamId": "19",
         "teamAbbr": "NYG",
         "teamName": "New York Giants",
         "history": [
          {
           "captured_at": "2026-09-22T07:21:27.433Z",
           "last_seen_at": "2026-09-22T21:39:08.409Z",
           "fp": "Active|2026-09-17T23:34Z|Tracy (illness) did not appear on the Giants' injury report Thursday, Dan Salomone of the team's official site reports.",
           "status": "Active",
           "date": "2026-09-17T23:34Z",
           "shortComment": "Tracy (illness) did not appear on the Giants' injury report Thursday, Dan Salomone of the team's official site reports.",
           "longComment": "Tracy was dealing with an illness to open the week, but he now appears to be back to full health. The running back logged just two snaps with the offense Week 1 against the Cowboys, losing a fumble on his second and final carry of the contest. Tracy figures to once again operate as the No. 3 option in the backfield behind starter Cam Skattebo and top backup Devin Singletary during Monday night's contest against the Rams."
          }
         ]
        },
        "637969": {
         "recordId": "637969",
         "athleteName": "Paulson Adebo",
         "positionAbbr": "CB",
         "teamId": "19",
         "teamAbbr": "NYG",
         "teamName": "New York Giants",
         "history": [
          {
           "captured_at": "2026-09-22T07:21:27.433Z",
           "last_seen_at": "2026-09-22T23:48:28.667Z",
           "fp": "Injured Reserve|2026-09-19T00:15Z|The Giants placed Adebo (knee) on injured reserve Friday, Dan Salomone of the team's official site reports.",
           "status": "Injured Reserve",
           "date": "2026-09-19T00:15Z",
           "shortComment": "The Giants placed Adebo (knee) on injured reserve Friday, Dan Salomone of the team's official site reports.",
           "longComment": "Adebo suffered a significant knee injury during last Sunday's win over the Cowboys. The cornerback made three solo tackles on 10 defensive snaps before exiting the game. The 27-year-old will now need to miss at least four games before he is eligible to return from IR. The Giants signed cornerback Nikko Reed to the active roster from the Chargers' practice squad in a corresponding move."
          }
         ]
        },
