        "638397": {
         "recordId": "638397",
         "athleteName": "Bhayshul Tuten",
         "positionAbbr": "RB",
         "teamId": "30",
         "teamAbbr": "JAX",
         "teamName": "Jacksonville Jaguars",
         "history": [
          {
           "captured_at": "2026-09-24T07:56:55.884Z",
           "last_seen_at": "2026-09-24T21:55:35.950Z",
           "fp": "Active|2026-09-21T02:45Z|Tuten rushed 13 times for 65 yards and a touchdown and brought in both targets for minus-3 yards in the Jaguars' 20-13 loss to the Broncos on Sunday.",
           "status": "Active",
           "date": "2026-09-21T02:45Z",
           "shortComment": "Tuten rushed 13 times for 65 yards and a touchdown and brought in both targets for minus-3 yards in the Jaguars' 20-13 loss to the Broncos on Sunday.",
           "longComment": "Tuten worked as the Jaguars' clear lead back for the second time in as many games to open the season, even though his rushing workload was relatively modest Sunday. Tuten got into the end zone for the first time this season on a one-yard run early in the second quarter, and he was efficient overall against a high-caliber defense. Tuten figures to remain in the same role for a Week 3 home showdown against the defending AFC champion Patriots next Sunday."
          }
         ]
        },
